#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param([ValidateSet('Receipt','Audit','Readback')][string]$Mode='Receipt')
$ErrorActionPreference='Stop'
$repo='<repo>'
$dir=Join-Path $repo 'docs/evidence/release15/strict-entry'
$session='Codex-20261031T142809Z-plugin-session';$request='req-20261031T142837Z-strict-entry-finish'
function Get-Pin([string]$Path){[ordered]@{path=$Path;sha256=(Get-FileHash -LiteralPath (Join-Path $repo $Path)).Hash}}
function Read-Receipt([string]$Folder){Get-Content (Join-Path $dir "$Folder/receipt.json") -Raw|ConvertFrom-Json}
if(-not $PSCmdlet.ShouldProcess($dir,"$Mode source evidence and own canonical audit")){return}
if($Mode -eq 'Receipt'){
 $mock=Read-Receipt 'mock-20261031T093659';$real=Read-Receipt 'real-20261031T094017';$prior=Read-Receipt 'Prior-20261031T094052';$checks=Read-Receipt 'Checks-20261031T094108'
 foreach($gate in @($mock,$real,$prior)){if($gate.exitCode -or $gate.failed -or $gate.skipped){throw 'Required focused gate failed'}}
 if($mock.cases -ne 28 -or $real.cases -ne 28 -or $prior.cases -ne 210){throw 'Case count differs'}
 $parity=(@($mock.names)-join "`n") -ceq (@($real.names)-join "`n")
 if(-not $parity){throw 'Mock/real oracle names differ'}
 foreach($pin in $mock.pins){$actual=@($real.pins|Where-Object path -CEQ $pin.path);if($actual.Count -ne 1 -or $actual[0].sha256 -cne $pin.sha256){throw 'Mock/real oracle bytes differ'}}
 $protected=Get-Content (Join-Path $dir 'protected-source.json') -Raw|ConvertFrom-Json
 $comparison=@(foreach($pin in $protected.files){[ordered]@{path=$pin.path;before=$pin.sha256;after=(Get-FileHash (Join-Path $repo $pin.path)).Hash;retainedOriginalSha256=(Get-FileHash $pin.copy).Hash}})
 $changed=@($comparison|Where-Object {$_.before -cne $_.after}|ForEach-Object path)
 if(@($changed|Where-Object {$_ -notin @('tests/browser/ui-command-acknowledgement.ts','tests/browser/live-multiplayer.integration.spec.ts')}).Count){throw 'Unexpected protected source change'}
 foreach($pin in $comparison){if($pin.before -cne $pin.retainedOriginalSha256){throw 'Original source copy drift'}}
 $edits=@(Get-ChildItem $dir -Directory|Where-Object Name -Match '^Edit-20261031'|Sort-Object Name|ForEach-Object {Read-Receipt $_.Name})
 if(@($edits|Where-Object {$_.hookExit -or $_.typecheckExit}).Count){throw 'Edit compile check failure'}
 $files=@('tests/browser/ui-command-entry.contract.ts','tests/browser/ui-command-entry.phase6.spec.ts','tests/browser/ui-command-entry.ts','tests/browser/ui-command-acknowledgement.ts','tests/browser/live-multiplayer.integration.spec.ts','playwright.ui-command.config.ts','docs/evidence/release15/strict-entry/plan.md')
 $native=@('mock-20261031T093659/browser.xml','real-20261031T094017/browser.xml','Prior-20261031T094052/unit.xml')
 $receipt=[ordered]@{atLocal=(Get-Date -Format s);kind='source repair evidence, not hostile approval';sessionId=$session;requestId=$request;parentSessionId='Codex-20261027T100516Z-plugin-session';parentRequestId='req-20261031T142639Z-release-resume';head=(& git -C $repo rev-parse HEAD).Trim();mock=$mock;real=$real;prior=$prior;checks=$checks;sameOracleCaseNames=$parity;sameOracleBytes=$true;negativeControlsPerBinding=14;malformedDomVariants=3;unknownPendingDomVariants=4;protectedSourceComparison=$comparison;changedProtectedSources=$changed;editChronology=$edits;sourcePins=@($files|ForEach-Object {Get-Pin $_});nativeFiles=@($native|ForEach-Object {Get-Pin "docs/evidence/release15/strict-entry/$_"});biomeWarnings=19;requirementsRead=(Get-Pin 'docs/evidence/release15/strict-entry/effective-current.json');ordinaryBrowserDiscovery='Existing playwright.phase6.config.ts *.phase6.spec.ts includes new spec; no config change needed.';failureHistory=@('mock-20261030T205056:28 launch failures, no assertions ran; browser absence preserved','mock-20261030T205155: partial log, no native terminal receipt; no test process existed at fresh inspection','mock-20261031T093354:7passed1failed20unrun, exit130 owned parent interrupt; hidden-role fixture and object-diff defect corrected beforeimplementation');limitations=@('Isolated actual Chromium DOM only; no live strict journey, push, token renewal, reconnect, autonomous worker, hosted or physical PWA acceptance established by these tests.','Historical failure missing-versus-denied exact probe remains unknown; no reconstructed DOM.','Full source-bound five-lane release gate and independent Cline Beam High review remain required.','Retirement observer forwarding source and old210 checked; new rejected observer DOM tests exercise fresh classifier boundary.','Existing historical TypeScript-sequence failures and all prior failed gate artifacts remain preserved; this slice later green does not erase them.','PowerShell scripts received PSSA Warning/Error checks before data use; explicit standalone parser check for new verifier/finalizer scripts recorded at final receipt generation.','Three early subagent chat timestamps were estimated; correction retained in oracle-before-correction-20261031T093227/manifest.json; native measured chronology governs.')}
 $receipt|ConvertTo-Json -Depth 16|Set-Content (Join-Path $dir 'receipt.json')
 Copy-Item -LiteralPath $PSCommandPath -Destination (Join-Path $dir 'receipt.producer.ps1')
 Copy-Item -LiteralPath /tmp/StrictEntryVerify.ps1 -Destination (Join-Path $dir 'verification.producer.ps1')
 Get-FileHash (Join-Path $dir 'receipt.json')|Select-Object Path,Hash|ConvertTo-Json
}elseif($Mode -eq 'Audit'){
 $result=& /tmp/StrictEntrySession.ps1 -Operation Invoke -Method workflow.sessionlog.appendActions -Parameters @{actions=@(@{order=4;type='edit';status='completed';filePath='tests/browser/ui-command-entry.ts';description='Implemented actual same-page visible/enabled action entry, optional actual blocked-condition phase, unchanged fresh guard, postfailure beforecleanup safe DOM capture and original failure propagation. Direct hook+tsc0.'},@{order=5;type='edit';status='completed';filePath='tests/browser/ui-command-acknowledgement.ts';description='Optional rejected-probe copy observer preserves original object and ordered distinct observer failure; forwards through strict/fresh/retire, all prior210 sources unchanged and210/0/0 native unit gate.'},@{order=6;type='edit';status='completed';filePath='tests/browser/live-multiplayer.integration.spec.ts';description='Adopted identical exact Locator entry+click, answerinput beforeguard, captured rejectedstate+PNGattempt beforefinally, unchanged game/push/deadline/conflict/solve assertions. Typecheck/lint/diff0;19lintwarnings retained.'},@{order=7;type='create';status='completed';filePath='docs/evidence/release15/strict-entry/receipt.json';description='Consolidated28/0/0mock and28/0/0real SAMEoracle bytes/nameparity,14negativecontrols each,210/0/0prior,8immediatehook/directtsc0checks,10unchangedprotected+2intendedchanges, priorfailurehistory and explicitisolatedlimitations.'})}|ConvertFrom-Yaml
 if($result.type -ne 'result'){throw 'Actions did not persist'}
 $result=& /tmp/StrictEntrySession.ps1 -Operation Invoke -Method workflow.sessionlog.updateTurn -Parameters @{response='SOURCE STOP. Focused isolatedDOMmock28/0/0 and identicalreal28/0/0; prior210/0/0; all8edit hook/directtsc0, finaltype/lint/diff0 with19warnings. All originalsources retained; no app/schema/policy/deps/bounds changes. No liveharness/build/HV/commit/push/deploy. Exact receipt docs/evidence/release15/strict-entry/receipt.json. Full strict runtime, complete release gates and independent Cline Beam High review remain required.';filesModified=@('tests/browser/ui-command-entry.contract.ts','tests/browser/ui-command-entry.phase6.spec.ts','tests/browser/ui-command-entry.ts','tests/browser/ui-command-acknowledgement.ts','tests/browser/live-multiplayer.integration.spec.ts','playwright.ui-command.config.ts','docs/evidence/release15/strict-entry/plan.md');designDecisions=@('Correct initial action readiness before unchanged fail-closed fresh guard, rather than swallowing rejected probes or weakening pending-state rules.','Causal mock checkpoint follows actual initial unmet DOM inspection; wrong probe completes actual read/classification before its signal. Same oracle and14negativecontrols bind real helpers.','Retain historical failed gate evidence; isolated source acceptance does not claim live strict success or hostile approval.')}|ConvertFrom-Yaml
 if($result.type -ne 'result'){throw 'Turn update did not persist'}
 $result=& /tmp/StrictEntrySession.ps1 -Operation Invoke -Method workflow.sessionlog.completeTurn -Parameters @{response='Source slice stopped after focused evidence preparation. Native28/0/0mock,28/0/0real,210/0/0prior;8immediatehook/directtsc0; finaltype/lint/diff0 with19warnings. Source receipt and chronological failures retained. No fullbuild/livejourney/HV/commit/push/deployment performed; parent owns frozen diagnostic/fullgate/HV.'}|ConvertFrom-Yaml
 if($result.type -ne 'result'){throw 'Turn completion did not persist'}
}else{
 $history=& /tmp/StrictEntrySession.ps1 -Operation Invoke -Method client.SessionLog.QueryAsync -Parameters @{agent='Codex';limit=60}|ConvertFrom-Yaml
 if($history.type -ne 'result'){throw 'Canonical query failed'}
 $turn=@(($history.payload.result.items|Where-Object sessionId -CEQ $session).turns|Where-Object requestId -CEQ $request)
 if($turn.Count -ne 1 -or $turn[0].status -ne 'completed' -or @($turn[0].actions).Count -lt 7){throw 'Canonical own audit readback did not match'}
 [ordered]@{atLocal=(Get-Date -Format s);sessionId=$session;requestId=$request;turn=$turn[0]}|ConvertTo-Json -Depth 40|Set-Content (Join-Path $dir 'canonical-readback.json')
 Get-FileHash (Join-Path $dir 'canonical-readback.json')|Select-Object Path,Hash|ConvertTo-Json
}
